# Test reraise as decorator with exception instance into
import sys
sys.path.insert(0, '/root/repo')

from funcy.flow import reraise

@reraise(ValueError, RuntimeError("custom message"))
def bad_func():
    raise ValueError("test")

try:
    bad_func()
except Exception as e:
    print(f"Caught: {type(e).__name__}: '{e}'")
